insert into public.leyes (id,titulo,siglas,fecha_publicacion,fecha_ultima_reforma,vigente,temas_clave,url_original,tipo) values ('15e6b367-4ea3-5120-a270-7252227965d3','Acuerdo de la Junta de Gobierno por el que se aprueban las Reglas para la determinación de Información de Interés Nacional','RDETERMINACION-IIN','2018-04-09',null,true,ARRAY['SNIEG','INEGI','Información de Interés Nacional','Propuestas de información','Criterios','Revocación']::text[],'https://www.snieg.mx/Documentos/Normatividad/Vigente/Reglas_Determinacion_Informacion_Interes_Nacional.pdf','acuerdo') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('b740e292-62e9-52d4-aff0-e0e033011682','Preámbulo','<p>INSTITUTO NACIONAL DE ESTADISTICA Y GEOGRAFIA ACUERDO de la Junta de Gobierno por el que se aprueban las Reglas para la determinación de Información de Interés Nacional. Al margen un sello con el Escudo Nacional, que dice: Estados Unidos Mexicanos.- Instituto Nacional de Estadística y Geografía.- Junta de Gobierno La Junta de Gobierno del Instituto Nacional de Estadística y Geografía, con fundamento en lo dispuesto por el Apartado B del artículo 26 de la Constitución Política de los Estados Unidos Mexicanos y los artículos 54, 55 fracciones I y II, 66, 77 fracciones II y VIII y 78 de la Ley del Sistema Nacional de Información Estadística y Geográfica, y</p><p>CONSIDERANDO</p><p>Que el Instituto Nacional de Estadística y Geografía (INEGI), en su carácter de organismo público autónomo, tiene por objeto, entre otros, normar y coordinar el Sistema Nacional de Información Estadística y Geográfica (SNIEG), cuya finalidad es suministrar a la sociedad y al Estado Información de Interés Nacional de calidad, pertinente, veraz y oportuna, sujeta a los principios de accesibilidad, transparencia, objetividad e independencia a efecto de coadyuvar al desarrollo nacional.</p><p>Que de conformidad con la Ley del Sistema Nacional de Información Estadística y Geográfica (LSNIEG), los objetivos del SNIEG son producir Información de Interés Nacional, difundirla oportunamente a través de mecanismos que faciliten su consulta, promover su conocimiento, uso y conservación. La Información de Interés Nacional, será oficial y de uso obligatorio para la Federación, las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México;</p><p>Que corresponde a la Junta de Gobierno del INEGI determinar la información que se considerará de Interés Nacional de manera adicional a la mencionada en el artículo 59 de la LSNIEG, por lo que, en respuesta a la necesidad de establecer los procedimientos que faciliten la presentación de propuestas para la determinación de Información de Interés Nacional, así como las que versen sobre la inclusión de temas o grupos de datos adicionales a los señalados en el artículo 78, fracción I de la LSNIEG, la Junta de Gobierno del INEGI ha tenido a bien emitir las siguientes: Reglas para la determinación de Información de Interés Nacional</p>','preambulo',1,'Reglas para la determinación de IIN',null,null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('e9184be4-4f1f-5556-8d8b-cfb5485ec7ad','Artículo 1','<p>Artículo 1.- Las presentes Reglas son de observancia general y obligatoria para las Unidades del Estado y tienen por objeto establecer las disposiciones conforme a las cuales se deben presentar las propuestas de información para que sea determinada como de Interés Nacional, así como las que se refieren a la inclusión de temas o grupos de datos adicionales a los señalados en el artículo 78, fracción I de la LSNIEG. Asimismo, determinan el procedimiento bajo el cual la Junta de Gobierno valorará y resolverá lo conducente respecto de las propuestas que le sean formuladas.</p>','ordinario',2,'Reglas para la determinación de IIN','Capítulo I · Disposiciones Generales',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('d0822dab-c202-54ab-a498-7c1ae5989222','Artículo 2','<p>Artículo 2.- Para efectos de las presentes Reglas, se entenderá por:</p><p>I. Accesibilidad: conjunto de condiciones bajo las cuales los usuarios pueden obtener Información Estadística y/o Geográfica.</p><p>II. Acervo de Información: conjunto de Información de Interés Nacional que ya ha sido difundida por el Servicio Público de Información, así como sus metadatos, metodologías y/o especificaciones concretas de la aplicación de las metodologías utilizadas en su generación.</p><p>III. Actividades Estadísticas y Geográficas o Actividades: relativas al diseño, captación, producción, actualización, organización, procesamiento, integración, compilación, publicación, divulgación y conservación de la Información de Interés Nacional.</p><p>IV. Calidad: grado en que un conjunto de características inherentes a los procesos y productos cumple con determinados atributos.</p><p>V. Comité Ejecutivo o CE: órgano colegiado de participación y consulta dentro de cada Subsistema Nacional de Información, facultado para opinar sobre el Programa Anual de Estadística y Geografía y supervisar su ejecución; revisar y proponer normas técnicas, Información de Interés Nacional, indicadores y metodologías.</p><p>VI. Comité Técnico Especializado o CTE: órgano colegiado de participación y consulta creado por acuerdo de la Junta de Gobierno, integrado por representantes de las Unidades del Estado y del Instituto, cuyo objetivo es contribuir al desarrollo de la Información Estadística y/o Geográfica, así como a la coordinación, integración y funcionamiento del Sistema.</p><p>VII. Consejo Consultivo Nacional o CCN: órgano colegiado de participación y consulta, encargado de opinar sobre asuntos que la Junta de Gobierno le solicite, así como sobre los Programas del SNIEG, y proponer a la Junta de Gobierno la creación de otros Subsistemas.</p><p>VIII. Independencia: característica de las Unidades del Estado para producir y difundir información libre de presiones de grupos de interés.</p><p>IX. INEGI: Instituto Nacional de Estadística y Geografía.</p><p>X. Información de Interés Nacional o IIN: la señalada en el artículo 59 de la Ley del Sistema Nacional de Información Estadística y Geográfica, así como aquella que la Junta de Gobierno determine como tal de acuerdo con lo establecido en los artículos 77, fracción II y 78 de dicha Ley.</p><p>XI. Información propuesta: grupo de datos y productos derivados de ellos, definido mediante la especificación de temas, subtemas, universos, cobertura espacial y temporal, periodicidad, escalas, proyecciones, variables u objetos espaciales, clasificaciones y parámetros que sean resultado de un operativo estadístico o geográfico determinado y puesto a consideración de la Junta de Gobierno para ser valorado y, en su caso, determinado como Información de Interés Nacional.</p><p>XII. Junta de Gobierno o JG: Junta de Gobierno del INEGI.</p><p>XIII. Ley o LSNIEG: Ley del Sistema Nacional de Información Estadística y Geográfica.</p><p>XIV. Metadatos: datos estructurados que describen las características del contenido, captura, procesamiento, calidad, condición, acceso y distribución de la Información Estadística o Geográfica.</p><p>XV. Metodología: procedimiento que ordena y articula el conjunto particular de actividades necesarias para producir información estadística y geográfica.</p><p>XVI. Metodología científicamente sustentada: aquella que responde a la aplicación del método científico que busca establecer la explicación de un fenómeno, de la que resulte una definición congruente con los datos de la observación. También se incluyen en esta categoría a las mejores prácticas y recomendaciones internacionales en la materia.</p><p>XVII. Objetividad: atributo que asegura que las Unidades del Estado generan y difunden información que refleje la realidad, tan fielmente como sea posible.</p><p>XVIII. Oportunidad: tiempo transcurrido entre que la Información está disponible para los usuarios y el hecho o fenómeno que describe.</p><p>XIX. Pertinencia: grado en que la Información Estadística y Geográfica responde a los requerimientos de los usuarios.</p><p>XX. Proponente: Unidad del Estado que presenta una propuesta de información para que sea determinada como de Interés Nacional de acuerdo con lo previsto en el artículo 78, de la LSNIEG.</p><p>XXI. Reglas: Reglas para la determinación de Información de Interés Nacional.</p><p>XXII. Sistema Nacional de Información Estadística y Geográfica o SNIEG: conjunto de Unidades del Estado organizadas a través de los Subsistemas y que son coordinadas por el INEGI y articuladas mediante la Red Nacional de Información, con el propósito de producir y difundir la Información de Interés Nacional.</p><p>XXIII. Subsistema Nacional de Información: componente del Sistema Nacional de Información Estadística y Geográfica, cuyo objetivo es producir, integrar, difundir y conservar Información de una determinada clase o respecto de temas específicos.</p><p>XXIV. Temas o Grupos de Datos: los considerados en la fracción I, del artículo 78 de la Ley y adicionados por la Junta de Gobierno de conformidad con el citado numeral y mediante el procedimiento establecido en estas Reglas.</p><p>XXV. Transparencia: condición en la que todas las políticas y prácticas que envuelven una Actividad Estadística o Geográfica se dan a conocer a los usuarios.</p><p>XXVI. Unidades del Estado o UE: a las áreas administrativas que cuentan con atribuciones para desarrollar Actividades Estadísticas y Geográficas o que cuentan con registros administrativos que permitan obtener Información de Interés Nacional de:</p><p>a) Las dependencias y entidades de la Administración Pública Federal, incluyendo a las de la Presidencia de la República y de la Procuraduría General de la República;</p><p>b) Los Poderes Legislativo y Judicial de la Federación;</p><p>c) Las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México;</p><p>d) Los organismos constitucionales autónomos, y</p><p>e) Los tribunales administrativos federales. Cuando el Instituto genere Información se considerará como Unidad del Estado.</p><p>XXVII. Veracidad: grado de aproximación de los cálculos o estimaciones a los valores exactos que la Información Estadística o Geográfica está destinada a representar.</p>','ordinario',3,'Reglas para la determinación de IIN','Capítulo I · Disposiciones Generales',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('a9f236d5-1e3f-5a03-8497-6f3e3233de17','Artículo 3','<p>Artículo 3.- La información estadística y geográfica de Interés Nacional, es aquélla indispensable para conocer la realidad del país en los aspectos demográficos, económicos, sociales, de gobierno, seguridad pública, justicia, así como geográficos, del medio ambiente y ordenamiento territorial y urbano, elaborada con base en una metodología científicamente sustentada y cuyo propósito es contribuir a la toma de decisiones para el diseño, implementación, seguimiento y evaluación de políticas públicas necesarias para el desarrollo del país.</p>','ordinario',4,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('fda6d861-6036-533a-acdd-94617aa236d4','Artículo 4','<p>Artículo 4.- La información de los Censos Nacionales, el Sistema de Cuentas Nacionales y los Índices Nacionales de Precios al Consumidor y Productor, es Información de Interés Nacional de acuerdo con lo establecido en el artículo 59 de la LSNIEG, así como aquella determinada como IIN por la Junta de Gobierno, de conformidad con el artículo 78 de la misma Ley. La Información de Interés Nacional, conforme a lo establecido en el artículo 6 de la Ley, es oficial y de uso obligatorio para la Federación, las entidades federativas, los municipios y las demarcaciones territoriales de la Ciudad de México, sin menoscabo de que las Unidades del Estado produzcan y publiquen información pública oficial adicional a la Información de Interés Nacional.</p>','ordinario',5,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('eae3bd3c-525f-5fc1-ae87-1fc833585248','Artículo 5','<p>Artículo 5.- Previo a la presentación de una propuesta de información para que sea determinada como de Interés Nacional, las Unidades del Estado deberán cerciorarse de que la misma tiene como propósito suministrar a la sociedad y al Estado información de calidad, pertinente, veraz y oportuna, lo que se asentará en los formatos a los que se refiere el artículo 11 segundo párrafo de estas Reglas.</p>','ordinario',6,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('227d9c74-186f-5b38-9c7c-66f51372de7e','Artículo 6','<p>Artículo 6.- Cumplido lo dispuesto en el artículo anterior, el primer criterio que debe considerar la Proponente para la determinación de alguna información como de Interés Nacional, es que se trate al menos de uno de los siguientes temas: población y dinámica demográfica; salud; educación; empleo; distribución de ingreso y pobreza; seguridad pública e impartición de justicia; gobierno; vivienda; sistema de cuentas nacionales; información financiera; precios; trabajo; ciencia y tecnología; telecomunicaciones y radiodifusión; atmósfera; biodiversidad; agua; suelo; flora; fauna; residuos peligrosos y residuos sólidos. En materia de información geográfica, la condición es que se trate de uno o varios de los siguientes grupos de datos: marco de referencia geodésico; límites costeros, internacionales, de las entidades federativas, municipales y de las demarcaciones territoriales de la Ciudad de México; datos de relieve continental, insular y submarino; datos catastrales, topográficos, de recursos naturales y clima, y nombres geográficos. La propuesta también podrá referirse a alguno de los nuevos temas o grupos de datos aprobados por la Junta de Gobierno, cuya incorporación se realizará conforme al procedimiento establecido en los artículos 31 a 34 de estas Reglas.</p>','ordinario',7,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('1ace1a56-5410-5839-981f-0f1a054bfe88','Artículo 7','<p>Artículo 7.- El segundo criterio que debe considerar la Proponente, es el establecido en la fracción II del artículo 78 de la Ley, que se refiere a que la información propuesta resulte necesaria para apoyar el diseño y la evaluación de políticas públicas de alcance nacional. Dicha necesidad puede sustentarse de acuerdo con lo siguiente:</p><p>I. Por derivar de ordenamientos legales, como la Constitución Política de los Estados Unidos Mexicanos y Leyes del Congreso de la Unión.</p><p>II. Por ser necesaria para el diagnóstico sobre temas nacionales que requieren atención por parte del Estado Mexicano.</p><p>III. Por ser necesaria para la formulación y evaluación de las políticas definidas en el Plan Nacional de Desarrollo vigente, así como en los Programas que de él emanen.</p>','ordinario',8,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('86f8900f-1ffd-5a61-b300-3ea299e7dd5d','Artículo 8','<p>Artículo 8.- El tercer criterio que debe considerar la Proponente, es el establecido en la fracción III del artículo 78 de la Ley, que refiere a que la información propuesta sea generada en forma regular y periódica. Se considerará como información generada en forma regular, aquella que se produzca o actualice dentro de periodos o etapas que aseguren su continuidad. Se considerará como información generada en forma periódica, aquella que se produzca con una frecuencia determinada y fija. No se considerará como incumplimiento de este criterio, cuando por causas asociadas a dificultades de financiamiento, caso fortuito o de fuerza mayor, la información propuesta no se genere de manera regular o periódica.</p>','ordinario',9,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('efe71b4e-d3c1-5ea5-9229-07837643d697','Artículo 9','<p>Artículo 9.- El cuarto criterio que debe considerar la Proponente, es el señalado por la fracción IV del artículo 78 de la Ley, el cual establece como condición que la información propuesta se elabore con base en una metodología científicamente sustentada, para lo cual el Secretario Técnico del CE correspondiente, deberá plasmar la opinión de los integrantes de dicho Comité en el dictamen técnico a que alude el artículo 16 de estas Reglas. Podrá acreditarse la satisfacción de este criterio cuando, a juicio de la Junta de Gobierno, se utilice una metodología que atienda las mejores prácticas nacionales o internacionales.</p>','ordinario',10,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('91623a09-ebf7-53c8-b1f8-749fc9485704','Artículo 10','<p>Artículo 10.- La Junta de Gobierno podrá considerar como Información de Interés Nacional la necesaria para la prevención y atención de emergencias o catástrofes originadas por eventos naturales, o la generada en virtud de un tratado internacional. Estos supuestos se consideran como casos de excepción por lo que no estarán sujetos a la observancia de las disposiciones contempladas en los artículos del 6 al 9 de estas Reglas. En el primer supuesto del presente artículo, la Información será reconocida como de Interés Nacional cuando se requiera para prevenir y/o atender desastres así declarados por el Sistema Nacional de Protección Civil y/o el Centro Nacional de Prevención de Desastres. En el segundo supuesto, el tratado internacional de que se trate deberá estar suscrito por el Presidente de la República y contar con la aprobación del Senado.</p>','ordinario',11,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección I · De los criterios para la formulación de propuestas de Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('04d41705-ddc6-5f04-9c4c-09ac79bd2ae8','Artículo 11','<p>Artículo 11.- Para la presentación de propuestas de información a determinarse como de Interés Nacional por la Junta de Gobierno, la Proponente deberá cumplir con los criterios previstos en los artículos 6 al 9 de estas Reglas. Las propuestas deberán presentarse por escrito en los formatos correspondientes a la información estadística o geográfica, los cuales estarán disponibles a través del Portal del SNIEG: www.snieg.mx. Los formatos deberán contener toda la información requerida en cada uno de sus apartados en los que se especificará, entre otros, la descripción de la información propuesta para ser determinada como de Interés Nacional, la metodología utilizada, los metadatos correspondientes, así como el calendario para su difusión cuando sea determinada como de Interés Nacional.</p>','ordinario',12,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección II · De los requisitos para la presentación de las propuestas','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('510d3744-cd32-5002-b9be-4d1fc084de00','Artículo 12','<p>Artículo 12.- Las propuestas de información que sean presentadas para ser analizadas y, en su caso, determinadas de Interés Nacional, deberán cumplir con las disposiciones normativas del Sistema que sean aplicables, con los principios rectores de accesibilidad, transparencia, objetividad e independencia, así como con los elementos de calidad, pertinencia, veracidad y oportunidad de la información propuesta, lo cual deberá quedar descrito en los apartados respectivos del formato correspondiente.</p>','ordinario',13,'Reglas para la determinación de IIN','Capítulo II · De la Información de Interés Nacional','Sección II · De los requisitos para la presentación de las propuestas','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('428c1911-c317-5229-a413-e2bdfebe3b18','Artículo 13','<p>Artículo 13.- La Proponente hará llegar su propuesta al Presidente del CTE al que corresponda la información de acuerdo al tema de que se trate. En caso de que no exista un CTE que atienda ese tema, será el CE del Subsistema competente el que reciba la propuesta, para que el Secretario Técnico de éste proceda a su atención debiendo realizar las acciones a que se refiere el artículo 15.</p>','ordinario',14,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('c850c0d9-33d5-5140-988c-e590ad5a7c65','Artículo 14','<p>Artículo 14.- Cuando la propuesta para la determinación de Información de Interés Nacional sea formulada por el pleno del CCN, será canalizada por su Presidente al CTE correspondiente, quien la valorará. La Unidad Proponente será la responsable de su generación. En este supuesto, el procedimiento para la valoración de la propuesta seguirá las etapas previstas a partir del siguiente artículo.</p>','ordinario',15,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('a572f9fe-6b3e-5429-b6ab-fd6472fb8f43','Artículo 15','<p>Artículo 15.- El Presidente del CTE recibirá la propuesta para su revisión y análisis. Conjuntamente con el Secretario Técnico verificarán el correcto y total llenado del formato y que la documentación soporte valide lo reportado en el mismo. En el supuesto de que la documentación soporte no esté completa, el Secretario Técnico lo hará del conocimiento de la Proponente para que atienda lo que le sea requerido. En un plazo no mayor a 60 días hábiles contados a partir de que se tenga la documentación completa, el Presidente del CTE deberá entregar al Presidente del CE del Subsistema correspondiente un informe con la resolución del análisis donde asentará la viabilidad de la propuesta, al que se adjuntará el formato y su documentación soporte. De ser necesario, el Presidente del CE podrá autorizar la ampliación del plazo establecido por un periodo de hasta 30 días hábiles.</p>','ordinario',16,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('209879ba-26ce-576b-97be-b996d66061c0','Artículo 16','<p>Artículo 16.- Una vez que el Presidente del CE reciba el informe del CTE, con una opinión favorable, el Secretario Técnico del CE elaborará un dictamen en el que se evalúa la conformidad con los criterios establecidos en los artículos del 6 al 9 de las Reglas. El dictamen técnico deberá presentarse para validación del pleno del CE en la siguiente sesión ordinaria o de considerarlo necesario, convocar a una sesión extraordinaria. En caso de que la opinión del CTE no sea favorable, se podrá solicitar a la Proponente, a través del Presidente del CTE, que realice las adecuaciones pertinentes y/o complemente la documentación para reiniciar el procedimiento, en un plazo no mayor a diez días hábiles contados a partir de la recepción de la solicitud de adecuaciones. De no tener respuesta en dicho plazo por parte de la Proponente, se tendrá por no validada la propuesta.</p>','ordinario',17,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('b0605d54-9ee9-50d1-9bba-cfba775e7358','Artículo 17','<p>Artículo 17.- Validada la propuesta por el pleno del CE, el Presidente del mismo lo remitirá y expondrá ante la Junta de Gobierno, conjuntamente con la Proponente si así lo requiere, en un periodo no mayor a tres meses contados a partir de la validación del dictamen mencionado.</p>','ordinario',18,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('6873c6b0-0407-5ff7-b0b5-f0b86abed62a','Artículo 18','<p>Artículo 18.- En caso de que la Junta de Gobierno requiera apoyo para valorar la propuesta, podrá invitar a servidores públicos del INEGI y expertos en el tema a que colaboren en la evaluación. Las personas designadas analizarán la propuesta y elaborarán un informe para que la Junta de Gobierno sustente su determinación.</p>','ordinario',19,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('948ac496-63fb-534c-a909-25fade6f1ced','Artículo 19','<p>Artículo 19.- De estimarlo procedente, la Junta de Gobierno solicitará al Presidente del CE para que por su conducto la Proponente precise la información respecto del o los criterios no satisfechos o, en su caso, se presente la documentación complementaria de manera que la propuesta vuelva a ser considerada por la Junta de Gobierno en el tiempo que determine.</p>','ordinario',20,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección I · De las etapas de valoración de la propuesta','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('5f13a8c3-3cec-5f58-8396-c44898dc9d06','Artículo 20','<p>Artículo 20.- Cuando la Junta de Gobierno realice una determinación de Información de Interés Nacional, emitirá el acuerdo respectivo que deberá ser publicado en el Diario Oficial de la Federación, en el que se precisará el fundamento legal, la determinación efectuada, su carácter oficial y uso obligatorio para la Federación, las entidades federativas, municipios y las demarcaciones territoriales de la Ciudad de México y la UE responsable de su producción.</p>','ordinario',21,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección II · De la resolución de la propuesta y su determinación como Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('3dd038de-fe9f-59b9-8d35-11f50c614d5d','Artículo 21','<p>Artículo 21.- La Información de Interés Nacional deberá difundirse a través del Servicio Público de Información, para lo cual se atenderán las disposiciones normativas en la materia.</p>','ordinario',22,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección II · De la resolución de la propuesta y su determinación como Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('ec6ac907-40ad-5556-bc67-4a71ce18978c','Artículo 22','<p>Artículo 22.- En el caso de que la Junta de Gobierno considere que alguna información sometida a su consideración no deba ser determinada como de Interés Nacional, emitirá el acuerdo correspondiente, y el Presidente del CE que la presentó notificará la decisión a la Proponente, indicando las razones de la determinación a la que adjuntará copia de la evaluación y el dictamen de la resolución.</p>','ordinario',23,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección II · De la resolución de la propuesta y su determinación como Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('fe53180e-4cdb-5ca9-b2a7-d35ed7087a96','Artículo 23','<p>Artículo 23.- El último trimestre del año, los Presidentes de los CE solicitarán a las Unidades del Estado las fechas de publicación de la Información de Interés Nacional que generan. Con base en ello elaborarán el calendario a que habrán de sujetarse durante el año inmediato siguiente, para su aprobación de la JG, a fin de que el Presidente del INEGI lo dé a conocer a los Poderes de la Unión y al público en general.</p>','ordinario',24,'Reglas para la determinación de IIN','Capítulo III · Del procedimiento para valorar y resolver las propuestas de Información de Interés Nacional','Sección II · De la resolución de la propuesta y su determinación como Información de Interés Nacional','15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('89651eaa-1f59-514c-9513-8907b214a761','Artículo 24','<p>Artículo 24.- La actualización de la Información de Interés Nacional no requerirá de acciones adicionales a las realizadas para su determinación cuando su periodicidad se contemple en los formatos aludidos y su metodología no requiera modificación.</p>','ordinario',25,'Reglas para la determinación de IIN','Capítulo IV · De la actualización de la Información de Interés Nacional y su metodología',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('94987d46-0898-5eb0-8492-e348ccc16474','Artículo 25','<p>Artículo 25.- El Presidente de cada CE, previo consenso con sus integrantes, solicitará a la JG que invite, al menos cada ocho años posteriores a la fecha de publicación de la IIN en el Diario Oficial de la Federación, a organismos internacionales para revisar y opinar sobre las metodologías que se utilizan en su producción. Como resultado de la consulta el Presidente del CE entregará a la JG el informe que corresponda con la documentación soporte, en el que se acredite el cumplimiento a lo dispuesto en el artículo 30 fracción VI de la LSNIEG.</p>','ordinario',26,'Reglas para la determinación de IIN','Capítulo IV · De la actualización de la Información de Interés Nacional y su metodología',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('853837c5-cb58-5af5-acd3-cf0467b3c635','Artículo 26','<p>Artículo 26.- Cuando se presente la necesidad de actualizar alguna metodología deberá someterse a consulta pública antes de su implementación, realizando lo siguiente:</p><p>I. La Proponente presentará la propuesta de actualización de la metodología al Secretario Técnico del CE quien revisará la solicitud y, de considerarlo procedente, tramitará ante la Dirección General de Coordinación del SNIEG vía oficio firmado por el Presidente del CE, la publicación de la actualización para su consulta pública en el Portal del SNIEG: www.snieg.mx, durante un periodo de 20 días hábiles, con la finalidad de recabar comentarios y opiniones de otras Unidades del Estado u otras instancias interesadas en el tema. El Presidente del CE determinará la conveniencia de ampliar el plazo de consulta hasta por 10 días hábiles, dando aviso a la Dirección General de Coordinación del SNIEG con cuando menos dos días antes de la conclusión del primer periodo.</p><p>II. Concluido el periodo de consulta pública, la Dirección General de Coordinación del SNIEG hará llegar al CE en un plazo máximo de 72 horas, el reporte con los comentarios recibidos para los efectos procedentes.</p><p>III. La Proponente revisará los comentarios y, en su caso, realizará las precisiones o modificaciones que estime procedentes. De no recibir comentarios u observaciones durante la consulta pública se entenderá que existe acuerdo tácito de la propuesta de metodología.</p><p>IV. El Presidente del CE enviará a la Junta de Gobierno un informe en el que se hará constar el resultado de la consulta pública, la validación del cambio de metodología, y si se manifestó o identificó alguna falta de concordancia con normas nacionales, internacionales o con las mejores prácticas en la materia.</p><p>V. Una vez que la JG verifique que el cambio de metodología no afecte el cumplimiento del criterio en la materia para continuar siendo Información de Interés Nacional, la aprobará e instruirá su difusión para el conocimiento público.</p>','ordinario',27,'Reglas para la determinación de IIN','Capítulo IV · De la actualización de la Información de Interés Nacional y su metodología',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('f1e756a3-e271-51b1-8519-3b1230772a46','Artículo 27','<p>Artículo 27.- Durante el tiempo en que sea sustanciado el procedimiento a que alude el artículo anterior, se continuará aplicando la metodología vigente en la producción de la Información de Interés Nacional de que se trate.</p>','ordinario',28,'Reglas para la determinación de IIN','Capítulo IV · De la actualización de la Información de Interés Nacional y su metodología',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('e574e12e-aa17-5a2b-bb96-f0b6305bd193','Artículo 28','<p>Artículo 28.- Los CE deberán revisar al menos cada tres años posteriores a la fecha de publicación en el Diario Oficial de la Federación, si la Información de Interés Nacional reúne los cuatro criterios mencionados en los artículos del 6 al 9 de estas Reglas Cuando la información deje de cumplir alguno de ellos, el Presidente del CE lo informará a la Junta de Gobierno para su revocación de conformidad con lo dispuesto en el artículo 30 de las Reglas.</p>','ordinario',29,'Reglas para la determinación de IIN','Capítulo V · De la revocación de la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('0238aa08-63b5-5496-8b43-aa9cb2f869e3','Artículo 29','<p>Artículo 29.- Cuando una UE considere que alguna Información de Interés Nacional dejó de satisfacer cualquiera de los criterios establecidos para su determinación, deberá justificarlo ante el pleno del CE para que, en caso de proceder, su Presidente solicite a la Junta de Gobierno la revocación del carácter de Información de Interés Nacional.</p>','ordinario',30,'Reglas para la determinación de IIN','Capítulo V · De la revocación de la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('8f4e18e6-6fbd-5e38-a015-d5a18282c9f0','Artículo 30','<p>Artículo 30.- La Junta de Gobierno analizará y resolverá la solicitud de revocación de Información de Interés Nacional y podrá determinar:</p><p>I.</p><p>Que es procedente, a través del acuerdo correspondiente en el que se expresarán las razones, motivos y fundamentos que respaldan su determinación. Dicho acuerdo será publicado en el Diario Oficial de la Federación y difundido mediante el Portal del SNIEG, para conocimiento del público en general. La Junta de Gobierno determinará la conservación de la Información revocada como fuente de información histórica, de conformidad con la normatividad aplicable.</p><p>II.</p><p>Que es improcedente, lo que hará del conocimiento del Presidente del Comité Ejecutivo solicitante, y la Información de Interés Nacional de que se trate seguirá vigente.</p>','ordinario',31,'Reglas para la determinación de IIN','Capítulo V · De la revocación de la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('2cd15977-ba40-5d0e-8d6c-bae5cda9634c','Artículo 31','<p>Artículo 31.- Cuando alguna información que se someta a consideración de la JG para su determinación como de Interés Nacional, verse sobre algún tema o grupo de datos no considerados en la fracción I, del artículo 78 de la Ley ni en los adicionados por la JG, las Unidades del Estado deberán proponer a la JG su incorporación, previa aprobación unánime del Consejo Consultivo Nacional. Cuando no medie una propuesta de Información de Interés Nacional y exista la necesidad de incorporar un nuevo tema, el Consejo Consultivo Nacional podrá proponerlo a la JG previa aprobación unánime de sus integrantes.</p>','ordinario',32,'Reglas para la determinación de IIN','Capítulo VI · Temas o grupos de datos',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('6062474e-7922-5560-bde6-b1fa113dbfb9','Artículo 32','<p>Artículo 32.- Por lo que se refiere al primer supuesto del artículo anterior, el Presidente del Comité Ejecutivo correspondiente será responsable de solicitar la incorporación del asunto en la agenda de la sesión del Consejo Consultivo Nacional, a solicitud de la Unidad del Estado.</p>','ordinario',33,'Reglas para la determinación de IIN','Capítulo VI · Temas o grupos de datos',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('67d9c4f4-80fd-5673-852e-741b3910de2f','Artículo 33','<p>Artículo 33.- Las propuestas sobre la adición de algún tema o grupo de datos realizada a la JG deberán formularse por escrito incluyendo los siguientes requisitos:</p><p>I. Denominación del tema o grupo de datos,</p><p>II. Las políticas públicas que para su diseño y evaluación requieren de la generación de Información de Interés Nacional sobre el tema o grupo de datos de referencia, y</p><p>III. La aprobación unánime del Consejo Consultivo Nacional.</p>','ordinario',34,'Reglas para la determinación de IIN','Capítulo VI · Temas o grupos de datos',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('373cd36e-b6d9-5e27-90c9-2a05fc5046a6','Artículo 34','<p>Artículo 34.- Una vez determinada por la JG la inclusión de temas o grupo de datos, le será comunicado al Comité Ejecutivo o, en su caso, al Consejo Consultivo Nacional, cuyos Presidentes notificarán la determinación de la JG a quien la propuso. El acuerdo de incorporación del tema o grupo de datos deberá publicarse en el Diario Oficial de la Federación y se incluirá en el listado respectivo en el Portal del SNIEG: www.snieg.mx.</p>','ordinario',35,'Reglas para la determinación de IIN','Capítulo VI · Temas o grupos de datos',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('26fafd9a-0f13-5862-b795-85911f8e1c02','Artículo 35','<p>Artículo 35.- La difusión de la Información de Interés Nacional a través del Servicio Público de Información atenderá lo dispuesto en las Reglas para la Prestación del Servicio Público de Información Estadística y Geográfica.</p>','ordinario',36,'Reglas para la determinación de IIN','Capítulo VII · De la difusión y conservación de la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('bb7f8b1c-a0bf-542b-959b-64770c2e86b6','Artículo 36','<p>Artículo 36.- La Información de Interés Nacional se conservará y resguardará en términos de lo previsto en las Reglas para la integración y administración del Acervo de Información de Interés Nacional.</p>','ordinario',37,'Reglas para la determinación de IIN','Capítulo VII · De la difusión y conservación de la Información de Interés Nacional',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('ed5ab0c9-7a46-54c1-a4a0-01dadc849679','Artículo 37','<p>Artículo 37.- La aplicación e interpretación de las presentes Reglas, para efectos administrativos corresponderá a la Junta de Gobierno, quien resolverá los casos no previstos por las mismas.</p>','ordinario',38,'Reglas para la determinación de IIN','Capítulo VIII · Interpretación',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('e714188f-3fce-5a1f-8b02-961887f5f7b2','Transitorio Primero','<p>PRIMERO.- Las Reglas para la determinación de Información de Interés Nacional aprobadas por el presente Acuerdo, entrarán en vigor el día siguiente de su publicación en el Diario Oficial de la Federación.</p>','transitorio',39,'Reglas para la determinación de IIN','Transitorios',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('ca488ef4-0f45-58d2-9cfd-b4dfb5d2b184','Transitorio Segundo','<p>SEGUNDO.- Se abrogan las Reglas para la determinación de la Información de Interés Nacional publicadas en el Diario Oficial de la Federación el 3 de septiembre de 2015.</p>','transitorio',40,'Reglas para la determinación de IIN','Transitorios',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('f6c51538-b7fc-5ec4-a9a7-e76a95d7f404','Transitorio Tercero','<p>TERCERO.- Para el caso de la Información de Interés Nacional vigente, el plazo establecido en el artículo 28 se contará a partir de la entrada en vigor de las presentes Reglas.</p>','transitorio',41,'Reglas para la determinación de IIN','Transitorios',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
insert into public.articulos (id,identificador,contenido,tipo_articulo,orden,titulo_nombre,capitulo_nombre,seccion_nombre,ley_id) values ('22b2d10f-9f20-55fc-9a0d-7dab9eb39cf6','Transitorio Cuarto','<p>CUARTO.- Los formatos a que se refiere el artículo 11, segundo párrafo de estas Reglas se actualizarán y difundirán en un periodo de 60 días hábiles posteriores a la publicación de las presentes Reglas. En tanto se actualizan dichos formatos seguirán aplicando los que actualmente se encuentran en el Portal del SNIEG: www.snieg.mx.</p>','transitorio',42,'Reglas para la determinación de IIN','Transitorios',null,'15e6b367-4ea3-5120-a270-7252227965d3') on conflict (id) do nothing;
